package java.util;
public interface NavigableMap<K,V> extends SortedMap<K,V> { Entry<K,V> lowerEntry(K k); K lowerKey(K k); Entry<K,V> floorEntry(K k); K floorKey(K k); Entry<K,V> ceilingEntry(K k); K ceilingKey(K k); Entry<K,V> higherEntry(K k); K higherKey(K k); Entry<K,V> firstEntry(); Entry<K,V> lastEntry(); Entry<K,V> pollFirstEntry(); Entry<K,V> pollLastEntry(); NavigableMap<K,V> descendingMap(); NavigableSet<K> navigableKeySet(); NavigableSet<K> descendingKeySet(); NavigableMap<K,V> subMap(K from,boolean fromInclusive,K to,boolean toInclusive); NavigableMap<K,V> headMap(K to,boolean inclusive); NavigableMap<K,V> tailMap(K from,boolean inclusive); SortedMap<K,V> subMap(K from,K to); SortedMap<K,V> headMap(K to); SortedMap<K,V> tailMap(K from); }
